(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(my*0.012-t*0.15)*8 + Math.cos(mx*0.01+t*0.1)*6;
  const w2y = Math.cos(mx*0.013+t*0.12)*8 + Math.sin(my*0.011-t*0.18)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.5],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.4],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.6],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.3],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.55],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.45],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.085, 1.8, 0.65]
  ];
  let aS=0, iS=0, cross=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp,amp]=src[i];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2,f2,sp2]=src[j];
      const d2=Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
      cross+=Math.sin((d*f-d2*f2)*0.5-t*(sp+sp2)*0.3)*0.15;
    }
  }
  const n=src.length;
  const act=aS/n, inh=iS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.05-ang*3-t*1.5), sp2=Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3=Math.sin(dist*0.03-ang*2+t*0.8)*0.5;
  const spiral=(sp1+sp2)*0.4+sp3*0.2;
  const c2x=160+Math.sin(t*0.2)*60, c2y=80+Math.cos(t*0.15)*40;
  const d2=Math.sqrt((sx-c2x)**2+(sy-c2y)**2), a2=Math.atan2(sy-c2y,sx-c2x);
  const spiral2=(Math.sin(d2*0.06+a2*3-t*1.8)+Math.sin(d2*0.045-a2*5+t*1.3))*0.25;
  const texture=Math.sin(sx*0.3)*Math.sin(sy*0.3)*Math.sin((sx-sy)*0.2+t*0.5)*0.15;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+spiral2+cross+texture)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const laplacian=(Math.sin(sx*0.2+t)*Math.cos(sy*0.2-t)+Math.sin(sx*0.15-sy*0.15+t*0.7))*0.2;
  const blend=reaction*0.6+cell*0.2+laplacian*0.2;
  const v=blend*0.5+0.5;
  const glow=Math.max(0, Math.sin(reaction*Math.PI*1.5))*0.3;
  const pal=[[6,12,52],[12,45,85],[18,90,120],[30,140,135],[80,175,140],[180,195,90],[220,170,65],[215,120,70],[180,70,80],[130,35,75],[70,18,60],[30,12,48],[6,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+glow;
  const edge=Math.abs(reaction)>0.65?1.12:Math.abs(reaction)>0.3?1.05:0.95;
  const depth=0.9+spiral*0.1;
  const m=lum*edge*depth;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
